const nav=document.createElement('button');nav.className='nav';nav.dataset.tab='comparison';nav.innerHTML='<span class="ui-icon ui-green" aria-hidden="true">⚖️</span><span class="nav-label">DIP × DPS</span>';document.querySelector('.menu-pages [data-tab="method"]').before(nav);
const tab=document.createElement('button');tab.setAttribute('role','tab');tab.setAttribute('aria-selected','false');tab.dataset.tab='comparison';tab.innerHTML='<span>DIP × DPS</span>';document.querySelector('.tabs [data-tab="method"]').before(tab);
const $=id=>document.getElementById(id),status=t=>{$('cmp-status').textContent=t;},active=()=>!section.hidden;
function sync(){for(const e of section.querySelectorAll('[data-cmp]'))if(!['dipProfile','dpsProfile'].includes(e.dataset.cmp))e.value=state[e.dataset.cmp];}
const summaryRows=r=>{const a=r.dip.end,b=r.dps.end;return [['Vaše vklady',a.own,b.own],['Příspěvky firmy',a.employer,b.employer],['Státní příspěvky',a.state,b.state],['Vstupní náklady',r.s.netReturns?'Obsaženo ve výnosu':a.entry,r.s.netReturns?'Obsaženo ve výnosu':b.entry],['Průběžná správa / náklady',r.s.netReturns?'Obsaženo ve výnosu':a.management,r.s.netReturns?'Obsaženo ve výnosu':b.management],['Výkonnostní úplata (odhad)',0,r.s.netReturns?'Obsaženo ve výnosu':b.performance],['Zhodnocení po nákladech',a.gain,b.gain],['Hodnota před výstupní daní',a.value,b.value],['Modelová daň z výnosu',a.tax,b.tax],['Po modelové dani / kapitál pro penzi',a.net,b.net],['Odpočet v pásmu 23 % / rok',r.taxDetails.dip.deduction23,r.taxDetails.dps.deduction23],['Odpočet v pásmu 15 % / rok',r.taxDetails.dip.deduction15,r.taxDetails.dps.deduction15],['Vliv zaokrouhlení základu na úsporu / rok',decimalMoney(r.taxDetails.dip.roundingEffect),decimalMoney(r.taxDetails.dps.roundingEffect)],['Daňová úspora / rok',r.annualTax.dip,r.annualTax.dps],['Daňová úspora mimo produkt',a.taxSaving,b.taxSaving],['Celkem včetně daňové úspory',a.total,b.total],['Celkem v dnešních cenách',a.real,b.real],['Bez krizového roku, včetně úspory daně',r.baseline.dip,r.baseline.dps],['Dopad krize proti hladkému modelu',a.total-r.baseline.dip,b.total-r.baseline.dps],['Největší modelový pokles jednotky',percent(r.dip.maxDrawdown*100,2),percent(r.dps.maxDrawdown*100,2)],['Volitelný bonus – hrubý odhad mimo součet',0,r.loyalty]];};
function render(){result=compare(state);state=result.s;const r=result;$('cmp-return-help').textContent=(state.netReturns?'Výnos je již po všech nákladech, včetně vstupního poplatku a průběžné správy. Žádný z uvedených poplatků neodečítáme podruhé. Stejně pracuje modul Můj DIP.':'Výnos je před náklady: ze zadaného výnosu odečítáme průběžné náklady i vstupní poplatek. Výsledek proto může být nižší.')+' Předpoklad vstupních poplatků: DIP '+number(state.dipEntry)+' %, DPS '+number(state.dpsEntry)+' %; roční správa DIP '+number(state.dipFee)+' %.';for(const kind of ['dip','dps']){const end=r[kind].end;$('cmp-'+kind+'-breakdown').textContent='Modelová daň při výběru '+money(end.tax)+' · daňová úspora mimo investici '+money(end.taxSaving)+' · souhrn po daních '+money(end.total)+'.';}for(const button of section.querySelectorAll('[data-shock-time]')){const timing=button.dataset.shockTime;const chosen=timing==='none'?!state.stress:!!state.stress&&state.shockYear===(timing==='early'?Math.min(2,state.years):timing==='middle'?Math.max(1,Math.round(state.years/2)):state.years);button.setAttribute('aria-pressed',String(chosen));}$('cmp-horizon').textContent='Za '+years(r.s.years)+' · v '+(r.s.age+r.s.years)+' letech';const strategyLabel=r.s.strategy==='permanent'?'Model Permanentního portfolia × akciový DPS (S&P 500 jako benchmark). ':r.s.strategy==='equal'?'Shodný čistý výnos a náklady. ':'Vlastní nastavení strategií. ';const scenario=r.s.stress?'AKTIVNÍ KRIZOVÝ ROK '+r.s.shockYear+': DIP '+number(r.s.dipShock)+' %, DPS '+number(r.s.dpsShock)+' %. Ostatní roky: DIP '+number(r.s.dipRate)+' %, DPS '+number(r.s.dpsRate)+' %.':'Aktivní model bez krize: každý rok stejná sazba. Propad není automatickou vlastností DPS ani jeho absence vlastností DIP.';$('cmp-scenario-note').textContent=strategyLabel+scenario;for(const k of ['shockYear','dipShock','dpsShock'])section.querySelector('[data-cmp='+k+']').disabled=!r.s.stress;section.querySelector('[data-cmp=shockYear]').max=r.s.years;section.querySelector('[data-cmp=shockYear]').value=r.s.shockYear;$('cmp-timing').replaceChildren(...stressCases(r.s).map(c=>{const tr=document.createElement('tr');for(const v of [c.label,c.year||'—',money(c.dip),money(c.dps),money(c.difference)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}return tr;}));const d=r.taxDetails.dip;$('cmp-tax-detail').textContent='Roční základ před odpočtem porovnávaného produktu: '+money(d.base)+'. Pásmo 15 %: '+money(d.base15)+'; pásmo 23 %: '+money(d.base23)+'. Roční úspora DIP: '+money(r.annualTax.dip)+'; DPS: '+money(r.annualTax.dps)+'. Zohledněn zbývající limit odpočtů, roční zaokrouhlení a základní sleva na poplatníka.';for(const kind of ['dip','dps'])$('cmp-'+kind).textContent=money(r[kind].end.value);$('cmp-verdict').textContent=(r.eligible&&r.excess===0?'Po modelových daních a daňových úsporách: ':'Pouze modelový rozdíl po daních a úsporách: ')+(Math.abs(r.difference)<1?'obě varianty vycházejí stejně.':'vychází '+(r.difference>0?'DIP':'DPS')+' o '+money(Math.abs(r.difference))+' lépe.');$('cmp-why').textContent='Aktivní zadání: DIP vstup '+number(state.dipEntry)+' %, roční náklady '+number(state.dipFee)+' % '+(state.netReturns?'(již v čistém výnosu)':'(odečítané navíc)')+'; DPS vstup '+number(state.dpsEntry)+' %, správa '+(state.netReturns?'již ve výnosu':number(state.dpsFee)+' % + '+number(state.dpsPerformance)+' % z kladného ročního zisku (odhad)')+'. Stát do DPS přidává '+money(r.support)+' měsíčně. Výnos DIP '+number(state.dipRate)+' %, DPS '+number(state.dpsRate)+' %. Výsledek není obecné pořadí produktů. '+scenario;const warnings=[];if(r.s.stress&&!r.s.netReturns&&r.s.dpsPerformance>0)warnings.push('POZOR: výkonnostní úplata DPS je v hrubém režimu zjednodušena a může po ztrátě nadhodnotit poplatek při zotavení; přesnou metodiku historických maxim konkrétního fondu model nezná. Pro strategický stresový test použijte čisté výnosy po všech průběžných nákladech.');if(!r.eligible)warnings.push('Horizont nesplňuje 10 let a věk 60. Částky nejsou řádně dostupné; předčasné ukončení by vyžadovalo další zdanění a vracení podpory.');if(r.excess)warnings.push('Nadlimitní příspěvek firmy '+money(r.excess)+' ročně: dodatečná daň a pojistné ze mzdy jsou mimo tento model.');if(state.loyalty)warnings.push(state.netReturns?'V čistém režimu nelze dopočítat bonus ze správy, která není samostatně vyčíslena.':'Volitelný model bonusu je mimo čistý součet; nejde o automatický nárok ani standardní podmínky DPS.');warnings.push('Pravidla ověřena k 30. 10. 2026; budoucí legislativa, příjmy a výnosy se mohou změnit.');warnings.push('Výkonnostní úplata DPS je zjednodušený odhad, nikoli přesný výpočet konkrétního fondu.');$('cmp-warning').textContent=warnings.join(' ');$('cmp-warning').classList.toggle('warning',!r.eligible||r.excess>0);
 $('cmp-summary').innerHTML=summaryRows(r).map(([t,a,b])=>`<tr><td>${t}</td><td>${typeof a==='number'?money(a):a}</td><td>${typeof b==='number'?money(b):b}</td></tr>`).join('');$('cmp-years').innerHTML=r.dip.rows.map((a,i)=>{const b=r.dps.rows[i];return `<tr><td>${a.year} / ${state.age+a.year}</td><td>${percent(a.annualReturn)}</td><td>${percent(b.annualReturn)}</td>${[a.value,b.value,a.net,b.net,a.taxSaving,b.taxSaving].map(x=>`<td>${money(x)}</td>`).join('')}</tr>`;}).join('');$('cmp-payout-note').textContent=(state.payout==='pension'?'DPS: kapitál pro penzi vyplácenou nejméně 10 let, nikoli jednorázová částka. ':'DPS: nová smlouva, jednorázově 15 % z kladného výnosu; příspěvek firmy se při řádné výplatě znovu nedaní. ')+(state.dipTax==='exempt'?'DIP: osvobození všech prodejů je vámi zvolený předpoklad; nenastává automaticky po 20 letech.':'DIP: hodnotový test 100 000 Kč a časový test každé investice samostatně; modelová sazba 15 / 23 % podle zadaného příjmu.');for(const k of ['dipFee','dpsFee','dpsPerformance'])section.querySelector('[data-cmp='+k+']').disabled=false;draw();}
function chartSvg(r,W=800,H=300){const L=65,R=15,T=20,B=35,max=Math.max(1,...r.points.flatMap(p=>[p.dip,p.dps,p.dipReal,p.dpsReal])),x=n=>L+n/r.s.years*(W-L-R),y=n=>H-B-n/max*(H-T-B);let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}"><title>Vývoj DIP a DPS po modelové dani včetně kumulované daňové úspory bez reinvestování</title>`;for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e8ddc8"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#75674f">${number(Math.round(v/1000))} tis.</text>`;}for(const [k,color,dash] of [['dip','#2563eb',''],['dps','#111111',''],['dipReal','#dc2626','4 4'],['dpsReal','#dc2626','10 5']])svg+=`<polyline fill="none" stroke="${color}" stroke-width="2.5" stroke-dasharray="${dash}" points="${r.points.map(p=>`${x(p.year)},${y(p[k])}`).join(' ')}"/>`;if(r.s.stress){const sx=x(r.s.shockYear-.5);svg+='<line x1="'+sx+'" x2="'+sx+'" y1="'+T+'" y2="'+(H-B)+'" stroke="#b45309" stroke-dasharray="3 5"/><text x="'+Math.min(W-R,sx)+'" y="15" text-anchor="end" font-size="11" fill="#9a5316">Krize: rok '+r.s.shockYear+'</text>';}for(const n of [...new Set([0,Math.round(r.s.years/2),r.s.years])])svg+=`<text x="${x(n)}" y="${H-9}" text-anchor="${n===0?'start':n===r.s.years?'end':'middle'}" font-size="12" fill="#75674f">${years(n)}</text>`;return svg+'</svg>';}
function draw(){if(result)$('cmp-chart').innerHTML=chartSvg(result,Math.max(280,$('cmp-chart').clientWidth||800));}
for(const e of section.querySelectorAll('[data-cmp]'))e.addEventListener('change',()=>{const k=e.dataset.cmp;activateCostMode(k);if(k==='dpsProfile'){if(e.value!=='custom'){state.dpsEntry=0;state.dpsFee=e.value==='conservative'?.4:1;state.dpsPerformance=e.value==='conservative'?10:15;sync();}}else if(k==='dipProfile'){if(e.value!=='custom'){state.dipEntry=e.value==='model'?3:0;state.dipFee=e.value==='model'?1.8:.4;sync();}}else{if(!e.checkValidity())return;state=cleanComparison({...state,[k]:e.value});if(['dpsEntry','dpsFee','dpsPerformance'].includes(k))section.querySelector('[data-cmp="dpsProfile"]').value='custom';if(['dipEntry','dipFee'].includes(k))section.querySelector('[data-cmp="dipProfile"]').value='custom';}render();});
for(const e of section.querySelectorAll('input[data-cmp]'))e.addEventListener('input',()=>{if(!e.checkValidity()||e.value==='')return;activateCostMode(e.dataset.cmp);state=cleanComparison({...state,[e.dataset.cmp]:Number(e.value)});if(['dpsEntry','dpsFee','dpsPerformance'].includes(e.dataset.cmp))section.querySelector('[data-cmp="dpsProfile"]').value='custom';if(['dipEntry','dipFee'].includes(e.dataset.cmp))section.querySelector('[data-cmp="dipProfile"]').value='custom';render();});
function save(){try{localStorage.setItem(key,JSON.stringify(state));status('Srovnání uloženo v tomto prohlížeči.');}catch{status('Uložení není dostupné. Použijte JSON export.');}}
function reset(){state={...COMP_EXAMPLE};sync();section.querySelector('[data-cmp="dipProfile"]').value='model';render();section.querySelector('[data-cmp="dpsProfile"]').value='dynamic';status('Obnoven výchozí příklad; uložená kopie zůstala zachována.');}
$('cmp-save').onclick=save;
const xml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const workbookSheet=rows=>`<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="1" width="45" customWidth="1"/><col min="2" max="8" width="24" customWidth="1"/></cols><sheetData>${rows.map((row,i)=>`<row r="${i+1}">${row.map((v,j)=>{const ref=String.fromCharCode(65+j)+(i+1);return typeof v==='number'?`<c r="${ref}"><v>${v}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`;}).join('')}</row>`).join('')}</sheetData></worksheet>`;
function reportRows(r){return [['DIP × DPS · MŮJ-DIP · Jiří Janoušek'],['Pravidla 2026, nové smlouvy. '+(r.eligible?'Řádný horizont.':'NESPLNĚN ŘÁDNÝ HORIZONT.')],['Položka','DIP Kč','DPS Kč'],...summaryRows(r),['Upozornění',disclaimer],['Metodika',methodology],['Strategie',r.s.strategy==='permanent'?'Model Permanentního portfolia × akciový DPS, S&P 500 jako benchmark':r.s.strategy==='equal'?'Shodné čisté parametry':'Vlastní nastavení'],['Rizikový scénář',"Rizikový scénář není prognóza ani historický backtest. V jednom zvoleném roce se běžný roční výnos nahradí krizovou sazbou pro každou strategii zvlášť; nejde o dodatečné procento navíc. Obě sazby se převedou na efektivní měsíční výnos, vklady pokračují na konci měsíců. Po krizovém roce se vrací původní sazba bez automatického dohánění ztráty. Výnosy zadávejte v CZK včetně zamýšleného vlivu měnového rizika a dividend. Model nezná budoucí kurz ani pravděpodobnost krize. Největší modelový pokles je počítán z vývoje jednotky po průběžných nákladech, bez nových vkladů, vstupního poplatku, výstupní daně a daňových úspor. Nejde o odhad skutečného maximálního propadu; skutečný pokles může být horší."],['Krizový rok',r.s.stress?r.s.shockYear:'Vypnut'],['Krizový výnos DIP / DPS',number(r.s.dipShock)+' % / '+number(r.s.dpsShock)+' %'],['Načasování krize: výsledky po dani a s úsporami','DIP Kč','DPS Kč'],...stressCases(r.s).map(c=>[c.label+(c.year?' / rok '+c.year:''),c.dip,c.dps]),['Výplata DPS',r.s.payout==='pension'?'Kapitál pro nejméně 10letou penzi, nikoli hotovost nyní.':'Jednorázová výplata.'],['DIP daň',r.s.dipTax+'; hodnotový test 100 000 Kč a modelové sazby 15 / 23 %, bez dividend a jiných nezadaných příjmů.'],['Volitelný bonus','Pouze ilustrační model 25 % správy do 65 let, nikoli standardní vlastnost DPS. Odhad je před případnou daní a mimo čistý součet.'],['Nadlimitní příspěvek firmy ročně',r.excess,'Dodatečné odvody nejsou zahrnuty.'],...sources.map(([t,u])=>[t,u])];}
function yearRows(r){return [['Rok','Věk','Zadaný výnos DIP %','Zadaný výnos DPS %','DIP před daní','DPS před daní','DIP po dani','DPS po dani','Úspora DIP','Úspora DPS'],...r.dip.rows.map((a,i)=>{const b=r.dps.rows[i];return [a.year,r.s.age+a.year,a.annualReturn,b.annualReturn,a.value,b.value,a.net,b.net,a.taxSaving,b.taxSaving];})];}
export function comparisonXlsx(r){const names=['Srovnani','Vyvoj','Nastaveni'],rows=[reportRows(r),yearRows(r),[['Nastavení DIP × DPS'],['Název','Hodnota'],...Object.entries(r.s).map(([k,v])=>[titles[k]||k,v])]],files={'[Content_Types].xml':`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${names.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`,'_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${names.map((n,i)=>`<sheet name="${n}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`,'xl/_rels/workbook.xml.rels':`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${names.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`};rows.forEach((v,i)=>files[`xl/worksheets/sheet${i+1}.xml`]=workbookSheet(v));return zip(files);}
async function imageExport(format,r){await document.fonts.ready;const W=1240,H=1754,pages=[];let c,g,y;const text=(t,x,yy,size=22,color='#242019')=>{g.font=`${size}px Arial`;g.fillStyle=color;g.fillText(String(t),x,yy);};const page=title=>{c=document.createElement('canvas');c.width=W;c.height=H;g=c.getContext('2d');g.fillStyle='#fffaf0';g.fillRect(0,0,W,H);text('MŮJ-DIP · Jiří Janoušek',70,65,22,'#9a7128');text(title,70,120,34);text('Orientační scénář bez záruky. Výnos není garantovaný.',70,H-55,19);pages.push(c);y=175;};const paragraph=t=>{const words=t.split(/\s+/).flatMap(w=>w.match(/.{1,65}/gu)||[]);let line='';for(const word of words){g.font='20px Arial';if(g.measureText(line+' '+word).width>1090){if(y>H-110)page('DIP × DPS · pokračování');text(line,70,y,20);y+=29;line=word;}else line+=(line?' ':'')+word;}if(line){text(line,70,y,20);y+=40;}};
page('DIP × DPS · přehled výsledků');paragraph(r.s.stress?'AKTIVNÍ KRIZOVÝ ROK '+r.s.shockYear+': DIP '+number(r.s.dipShock)+' %, DPS '+number(r.s.dpsShock)+' %. Běžný výnos v ostatních letech: DIP '+number(r.s.dipRate)+' %, DPS '+number(r.s.dpsRate)+' %.':'Aktivní model bez krizového roku.');paragraph(`${years(r.s.years)} · věk ${r.s.age} až ${r.s.age+r.s.years} · vlastní ${money(r.s.own)} / měsíc · firma ${money(r.s.employer)} / měsíc. ${r.eligible?'Řádný horizont.':'POZOR: nesplněny podmínky řádné výplaty.'}`);paragraph(`DIP: výnos ${percent(r.s.dipRate)}, vstup ${percent(r.s.dipEntry)}, roční náklady ${percent(r.s.dipFee)}. DPS: výnos ${percent(r.s.dpsRate)}, vstup ${percent(r.s.dpsEntry)}, správa ${percent(r.s.dpsFee)}, výkonnostní úplata ${percent(r.s.dpsPerformance)}. ${r.s.netReturns?'Výnosy již po průběžných nákladech.':'Výnosy před náklady.'}`);
text('Položka',70,y,21);text('DIP',660,y,21,'#2563eb');text('DPS',920,y,21,'#111111');y+=40;for(const [t,a,b] of summaryRows(r)){text(t.startsWith('Volitelný bonus')?'Volitelný bonus (hrubý odhad mimo součet)':t,70,y,19);text(typeof a==='number'?money(a):a,660,y,19);text(typeof b==='number'?money(b):b,920,y,19);y+=39;}
if(y+375>H-110)page('DIP × DPS · graf a riziko');const svg=chartSvg(r,1100,340),img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});g.drawImage(img,70,y,1100,340);y+=375;}finally{URL.revokeObjectURL(url);}paragraph('Graf: DIP modře, DPS černě, kupní síla po inflaci červeně (DIP krátké / DPS dlouhé čárky). Po modelové dani při řádném výběru v daném roce včetně kumulované daňové úspory mimo produkt, bez jejího reinvestování. Koncové hodnoty odpovídají součtům v přehledu. Daň není průběžně odečítána každý rok.');
page('DIP × DPS · riziko a načasování');paragraph(r.s.strategy==='permanent'?'Model Permanentního portfolia vs. akciový DPS s rizikovým benchmarkem S&P 500. Nejde o skutečný dvacetiletý backtest konkrétních fondů.':r.s.strategy==='equal'?'Stejný čistý výnos a náklady obou strategií; daně a podpora podle produktu.':'Vlastní model strategií.');paragraph("Rizikový scénář není prognóza ani historický backtest. V jednom zvoleném roce se běžný roční výnos nahradí krizovou sazbou pro každou strategii zvlášť; nejde o dodatečné procento navíc. Obě sazby se převedou na efektivní měsíční výnos, vklady pokračují na konci měsíců. Po krizovém roce se vrací původní sazba bez automatického dohánění ztráty. Výnosy zadávejte v CZK včetně zamýšleného vlivu měnového rizika a dividend. Model nezná budoucí kurz ani pravděpodobnost krize. Největší modelový pokles je počítán z vývoje jednotky po průběžných nákladech, bez nových vkladů, vstupního poplatku, výstupní daně a daňových úspor. Nejde o odhad skutečného maximálního propadu; skutečný pokles může být horší.");paragraph(r.s.stress?'Aktivní krizový rok '+r.s.shockYear+': DIP '+number(r.s.dipShock)+' %, DPS '+number(r.s.dpsShock)+' %.':'Aktivní hladký model bez krize.');for(const c of stressCases(r.s))paragraph(c.label+(c.year?' / rok '+c.year:'')+': DIP '+money(c.dip)+', DPS '+money(c.dps)+'.');page('DIP × DPS · nastavení a metodika');for(const [k,v] of Object.entries(r.s))paragraph((titles[k]||k)+': '+v);paragraph(methodology);paragraph(disclaimer);paragraph('DIP daň: režim test posuzuje hrubé prodeje do 100 000 Kč a stáří každého nákupu. Neosvobozený zisk podléhá modelu 15 / 23 % podle uvedeného příjmu. Dividendy a nezadané příjmy nejsou zahrnuty.');paragraph(r.s.payout==='pension'?'DPS: kapitál pro penzi alespoň 10 let, bez diskontování a následného zhodnocení. Nejde o jednorázovou hotovost.':'DPS: nová smlouva, jednorázová daň 15 % kladného výnosu; příspěvky zaměstnavatele při řádné výplatě bez další daně.');if(r.excess)paragraph('POZOR: roční nadlimitní příspěvek firmy '+money(r.excess)+'; dodatečná daň a odvody mimo výpočet.');for(const [t,u] of sources){paragraph(t);paragraph(u);}
page('DIP × DPS · roční vývoj');paragraph('Řádná výstupní daň je modelová; před splněním podmínek částky nejsou dostupné bez dopadů předčasného ukončení. Částky v Kč; úspory daně nejsou v hodnotě portfolia.');const heads=()=>{['Rok / věk','DIP před daní','DPS před daní','DIP po dani','DPS po dani'].forEach((t,i)=>text(t,[70,270,510,750,990][i],y,17));y+=40;};heads();for(const a of r.dip.rows){if(y>H-120){page('DIP × DPS · vývoj pokračování');heads();}const b=r.dps.rows[a.year-1];[`${a.year} / ${r.s.age+a.year}`,...[a.value,b.value,a.net,b.net].map(n=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:0}).format(n))].forEach((t,i)=>text(t,[70,270,510,750,990][i],y,18));y+=37;}
if(format==='png'){const all=document.createElement('canvas');all.width=W;all.height=H*pages.length;if(all.height>30000)throw Error('Výstup je příliš dlouhý pro PNG. Použijte PDF.');const ctx=all.getContext('2d');pages.forEach((p,i)=>ctx.drawImage(p,0,i*H));const blob=await new Promise(resolve=>all.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG se nepodařilo vytvořit.');saveFile('MUJ-DIP-DPS-srovnani.png',blob,'image/png');}else{const images=pages.map(p=>Uint8Array.from(atob(p.toDataURL('image/jpeg',.92).split(',')[1]),ch=>ch.charCodeAt(0)));saveFile('MUJ-DIP-DPS-srovnani.pdf',jpegPdf(images,W,H),'application/pdf');}}
function comparisonReport(r){return {id:'srovnani',title:'DIP × DPS – srovnání modelových scénářů',subtitle:'Po modelové dani při řádné výplatě včetně daňových úspor mimo produkt. Alternativy se nesčítají.',summary:[['Doba investování (let)',r.s.years],['Výsledná hodnota DIP včetně úspory daně',r.dip.end.total],['Výsledná hodnota DPS včetně úspory daně',r.dps.end.total],['Rozdíl DIP − DPS',r.difference],...summaryRows(r).slice(0,9).map(([label,dip,dps])=>[label+' – DIP / DPS',money(dip)+' / '+money(dps)])],settings:Object.entries(r.s).map(([k,v])=>[titles[k]||k,v]),headers:yearRows(r)[0],rows:yearRows(r).slice(1),chart:{type:'line',title:'Vývoj po modelové dani včetně daňových úspor',categories:r.points.map(p=>p.year),series:[['dip','DIP','#2563eb'],['dps','DPS','#111111'],['dipReal','DIP po inflaci','#dc2626'],['dpsReal','DPS po inflaci','#a63b32']].map(([key,name,color])=>({name,color,values:r.points.map(p=>p[key])}))},notes:[methodology,r.eligible?'Horizont splňuje podmínky řádné výplaty.':'POZOR: nejsou splněny podmínky řádné výplaty. Předčasný výběr a vracení podpory nejsou modelovány.','Riziko určuje investiční strategie. Zadané propady nejsou automatickými vlastnostmi DIP nebo DPS.',r.s.stress?'Aktivní krizový rok '+r.s.shockYear+': DIP '+r.s.dipShock+' %, DPS '+r.s.dpsShock+' %.':'Aktivní model bez krizového roku.',...sources.map(([label,url])=>label+': '+url)],disclaimer:disclaimer};}
async function exportComparison(format){try{status('Připravuji výstup…');if(format==='xlsx'||format==='pdf')await exportModule(comparisonReport(result),format);else if(format==='csv')saveFile('MUJ-DIP-DPS-vyvoj.csv','\uFEFF'+yearRows(result).map(row=>row.map(v=>typeof v==='number'?v.toFixed(2):v).join(';')).join('\r\n'),'text/csv;charset=utf-8');else if(format==='json')saveFile('MUJ-DIP-DPS-plan.json',JSON.stringify({app:'MUJ-DIP-DPS',version:1,settings:state},null,2),'application/json');else await imageExport(format,result);status('Srovnání je připraveno ke stažení.');}catch(e){status('Export se nezdařil: '+e.message);}}
for(const e of section.querySelectorAll('[data-cmp-export]'))e.onclick=()=>exportComparison(e.dataset.cmpExport);
async function importComparison(file){if(!file)return;try{if(file.size>100000)throw Error('Soubor je příliš velký.');const data=JSON.parse(await file.text());if(data.app!=='MUJ-DIP-DPS'||data.version!==1||!data.settings||Object.keys(COMP_DEFAULTS).some(k=>!['otherSales','stress','shockYear','dipShock','dpsShock','strategy'].includes(k)&&!(k in data.settings)))throw Error('Použijte JSON export srovnání DIP × DPS.');for(const k in COMP_DEFAULTS){if(['dipTax','payout','strategy'].includes(k)||['otherSales','stress','shockYear','dipShock','dpsShock','strategy'].includes(k)&&!(k in data.settings))continue;if(typeof data.settings[k]!=='number'||!Number.isFinite(data.settings[k]))throw Error('Neplatné číselné nastavení.');}state=cleanComparison(data.settings);sync();section.querySelector('[data-cmp="dipProfile"]').value='custom';section.querySelector('[data-cmp="dpsProfile"]').value='custom';render();status('Srovnání načteno.');}catch(e){status('Import: '+e.message);}}
$('cmp-import').onchange=async e=>{await importComparison(e.target.files[0]);e.target.value='';};
for(const [id,handler] of [['save',save],['reset',reset],['export',()=>exportComparison($('exportFormat').value)],['print',()=>exportComparison('pdf')]])$(id).addEventListener('click',e=>{if(active()){e.preventDefault();e.stopImmediatePropagation();handler();}},true);
$('import').addEventListener('change',async e=>{if(!active())return;e.stopImmediatePropagation();await importComparison(e.target.files[0]);e.target.value='';},true);
if(state.dpsFee!==1||state.dpsPerformance!==15||state.dpsEntry!==0)section.querySelector('[data-cmp="dpsProfile"]').value='custom';new ResizeObserver(draw).observe($('cmp-chart'));sync();if(state.dipFee!==1.8||state.dipEntry!==3)section.querySelector('[data-cmp="dipProfile"]').value='custom';render();


function scenarioPreset(kind){if(kind==='equal')state=cleanComparison({...state,strategy:'equal',netReturns:1,dipRate:7,dpsRate:7,dipEntry:0,dpsEntry:0,dipFee:1.8,dpsFee:1,dpsPerformance:15,stress:0});else state=cleanComparison({...state,strategy:'permanent',netReturns:0,dipRate:7,dpsRate:7,dipEntry:3,dpsEntry:0,dipFee:1.8,dpsFee:1,dpsPerformance:15,stress:1,shockYear:state.years,dipShock:-15,dpsShock:-35});sync();section.querySelector('[data-cmp=dipProfile]').value='custom';section.querySelector('[data-cmp=dpsProfile]').value='custom';render();status('Nastaven model. Vlastní a firemní vklady, mzda a způsob výplaty zachovány. Sazby můžete upravit.');}
$('cmp-equal').onclick=()=>scenarioPreset('equal');$('cmp-strategies').onclick=()=>scenarioPreset('strategies');for(const b of section.querySelectorAll('[data-shock-time]'))b.onclick=()=>{state=cleanComparison({...state,stress:b.dataset.shockTime==='none'?0:1,shockYear:b.dataset.shockTime==='none'?state.shockYear:b.dataset.shockTime==='early'?Math.min(2,state.years):b.dataset.shockTime==='middle'?Math.max(1,Math.round(state.years/2)):state.years});sync();render();};

function activateCostMode(k){if(['dipFee','dpsFee','dpsPerformance','dipProfile','dpsProfile','dipEntry','dpsEntry'].includes(k)&&state.netReturns){status('Výnos je již po všech nákladech. Změněné sazby se proto znovu neodečítají; pro jejich samostatný dopad zvolte výnos před poplatky.');}}

for(const button of section.querySelectorAll('[data-performance]'))button.addEventListener('click',()=>{state=cleanComparison({...state,dpsPerformance:Number(button.dataset.performance)});sync();section.querySelector('[data-cmp=dpsProfile]').value='custom';render();status('Výkonnostní poplatek DPS: '+number(state.dpsPerformance)+' %. Při čistém výnosu je již obsažen, v hrubém režimu se odečítá zvlášť.');});


$('cmp-export-pdf').addEventListener('click',()=>exportComparison('pdf'));
